// The per-kit graph canvas (#2863) — a language kit's OWN graph: nodes are its implementations (a
// concept IS its implementation), wired by `composes` (builds-on) + `pairs` + the ontology's semantic
// relationships lifted onto the concrete impls. World-positioned impl cards over an SVG edge layer
// (GraphCanvas owns the pan/zoom transform) so it reads like every other graph. Selection lights a
// node + its neighbors. The role distinguishes the card (#2980): a primitive is a language built-in
// (#2972) — a violet dashed descriptor chip showing its std `ref` — vs an algorithm's solid card.
import { useMemo } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { graphEdge } from "@/shared/lib/graph/edgePath";
import {
  KIT_REL_META, NODE_W, NODE_H, GROUP_W, GROUP_H, stubNodeId,
  type KitGraph, type KnowledgeLayout, type GroupNode, type GroupEdge, type GroupStub,
} from "@/features/algorithms/lib/knowledge";

interface KitEdgeGeom {
  id: string; label: string; dashed: boolean; from: string; to: string;
  d: string; arrow: string; arrowStart?: string; labelX: number; labelY: number;
}

/** How a GROUP edge reads (`the-algorithms-group-layer-draws-its-links`): a crate dependency is the layer's
 *  real structure and draws solid; a bundle of implementations composing across two groups draws dashed,
 *  so the two stay distinguishable — the legend keys the same pair. */
const GROUP_REL_META: Record<GroupEdge["rel"], { label: string; dashed: boolean }> = {
  depends: { label: "depends on", dashed: false },
  composes: { label: "composes", dashed: true },
};

export function AlgorithmsKitGraph({ kit, layout, selected, onSelect, groups = [], groupEdges = [], stubs = [], onEnter }: {
  kit: KitGraph;
  layout: KnowledgeLayout;
  /** The selected implementation id, or null. */
  selected: string | null;
  onSelect: (id: string) => void;
  /** The GROUPS this layer draws instead of implementations — empty on a drilled layer. */
  groups?: readonly GroupNode[];
  /** The edges BETWEEN those groups — crate dependencies and bundled cross-group composes. A group layer's
   *  `kit` is empty, so without these the canvas drew cards and no lines while the header counted links
   *  (`the-algorithms-group-layer-draws-its-links`). */
  groupEdges?: readonly GroupEdge[];
  /** The links that leave a drilled group — empty on the top layer. */
  stubs?: readonly GroupStub[];
  /** Drill into a group or follow a stub. Absent where nothing can be entered. */
  onEnter?: (id: string) => void;
}) {
  // Neighbors of the selection (either direction) + the incident edges — the shared "focus dims the rest".
  const lit = useMemo(() => {
    if (!selected) return null;
    const nodes = new Set<string>([selected]);
    const edges = new Set<string>();
    for (const e of kit.edges) {
      const id = `${e.from}~${e.rel}~${e.to}`;
      if (e.from === selected) { nodes.add(e.to); edges.add(id); }
      if (e.to === selected) { nodes.add(e.from); edges.add(id); }
    }
    return { nodes, edges };
  }, [kit.edges, selected]);

  // Edge geometry — bow parallel edges between the same pair apart so they don't overdraw.
  const geoms = useMemo<KitEdgeGeom[]>(() => {
    // Kit edges and group edges share one list: a layer holds one or the other, and the bowing below has
    // to see every edge between a pair to keep a depends and a composes between the same two groups apart.
    // Each carries the card size of what it joins — a group card is not an impl card.
    const all = [
      ...kit.edges.map((e) => ({ from: e.from, to: e.to, rel: e.rel as string, w: NODE_W, h: NODE_H,
        label: KIT_REL_META[e.rel].label, dashed: !!KIT_REL_META[e.rel].dashed, doubleEnded: KIT_REL_META[e.rel].doubleEnded })),
      ...groupEdges.map((e) => ({ from: e.from, to: e.to, rel: e.rel as string, w: GROUP_W, h: GROUP_H,
        label: GROUP_REL_META[e.rel].label, dashed: GROUP_REL_META[e.rel].dashed, doubleEnded: false })),
    ];
    const pairKey = (a: string, b: string) => (a < b ? `${a}|${b}` : `${b}|${a}`);
    const counts = new Map<string, number>();
    for (const e of all) counts.set(pairKey(e.from, e.to), (counts.get(pairKey(e.from, e.to)) ?? 0) + 1);
    const seen = new Map<string, number>();
    return all.flatMap((e) => {
      const a = layout.pos.get(e.from), b = layout.pos.get(e.to);
      if (!a || !b) return [];
      const key = pairKey(e.from, e.to);
      const n = counts.get(key)!;
      const i = seen.get(key) ?? 0;
      seen.set(key, i + 1);
      const bow = n > 1 ? (i - (n - 1) / 2) * 20 : 0;
      const g = graphEdge(
        { x: a.x, y: a.y, w: e.w, h: e.h },
        { x: b.x, y: b.y, w: e.w, h: e.h },
        { routing: "anchor", bow, doubleEnded: e.doubleEnded },
      );
      return [{ id: `${e.from}~${e.rel}~${e.to}`, label: e.label, dashed: e.dashed, from: e.from, to: e.to, ...g }];
    });
  }, [kit.edges, groupEdges, layout.pos]);

  return (
    <>
      <svg width={layout.world.w} height={layout.world.h} style={{ position: "absolute", left: 0, top: 0, overflow: "visible", pointerEvents: "none" }}>
        {geoms.map((g) => {
          const isLit = !!lit && lit.edges.has(g.id);
          const dim = !!lit && !isLit;
          const stroke = isLit ? "var(--fg-dim)" : "var(--border)";
          return (
            <g key={g.id} style={{ opacity: dim ? 0.14 : 1, transition: "opacity 0.16s ease" }}>
              <path d={g.d} fill="none" stroke={stroke} strokeWidth={isLit ? 1.75 : 1.25}
                strokeDasharray={g.dashed ? "4 4" : undefined} />
              <path d={g.arrow} fill={stroke} />
              {g.arrowStart && <path d={g.arrowStart} fill={stroke} />}
              {isLit && (
                <text className="algo-edgelabel" x={g.labelX} y={g.labelY} textAnchor="middle" dominantBaseline="middle">
                  {g.label}
                </text>
              )}
            </g>
          );
        })}
      </svg>

      {/* GROUP cards (`the-algorithms-graph-drills-by-crate`) — a crate, a feature folder, or a sub-folder of
          one that was over the cap. Drawn on the same canvas as impl cards because a layer is either groups or
          implementations, never both, and one renderer keeps the two reading alike. */}
      {groups.map((g) => {
        const p = layout.pos.get(g.id);
        if (!p) return null;
        const dim = !!lit && !lit.nodes.has(g.id);
        return (
          <Box
            key={g.id}
            data-group={g.id}
            className={`algo-node algo-group${g.id === selected ? " on" : ""}${dim ? " dim" : ""}`}
            style={{ left: p.x, top: p.y, width: GROUP_W, height: GROUP_H }}
            // A group card has nothing to inspect — its members are one layer down — so a CLICK ENTERS it.
            // Selecting it instead would make navigation a double-click, which is the gesture this page
            // exists to avoid: fewer nodes on screen is only an improvement if reaching them is easy.
            onClick={(e) => { e.stopPropagation(); onEnter?.(g.id); }}
            title={`${g.label} — ${g.count} implementation${g.count === 1 ? "" : "s"}`}
          >
            <Box as="span" className="algo-name">{g.label}</Box>
            <Box as="span" className="algo-meta mono">{g.count} impls · {g.kind}</Box>
          </Box>
        );
      })}

      {/* STUBS — the edges that LEAVE this group, kept visible rather than dropped. Entering one drills there. */}
      {stubs.map((s) => {
        const p = layout.pos.get(stubNodeId(s));
        if (!p) return null;
        return (
          <Box
            key={stubNodeId(s)}
            data-stub={s.id}
            className="algo-node algo-stub"
            style={{ left: p.x, top: p.y, width: GROUP_W, height: GROUP_H }}
            onClick={(e) => { e.stopPropagation(); onEnter?.(s.id); }}
            title={`${s.count} edge${s.count === 1 ? "" : "s"} ${s.direction === "out" ? "into" : "from"} ${s.label}`}
          >
            <Box as="span" className="algo-name">{s.direction === "out" ? "→" : "←"} {s.label}</Box>
            <Box as="span" className="algo-meta mono">{s.count} edge{s.count === 1 ? "" : "s"}</Box>
          </Box>
        );
      })}

      {kit.nodes.map((im) => {
        const p = layout.pos.get(im.id);
        if (!p) return null;
        const dim = !!lit && !lit.nodes.has(im.id);
        return (
          <Box
            key={im.id}
            data-impl={im.id}
            className={`algo-node${im.role === "primitive" ? " algo-prim" : ""}${im.id === selected ? " on" : ""}${dim ? " dim" : ""}`}
            style={{ left: p.x, top: p.y, width: NODE_W, height: NODE_H }}
            onClick={(e) => { e.stopPropagation(); onSelect(im.id); }}
          >
            <Box as="span" className="algo-name">{im.name}</Box>
            {/* A primitive is a language built-in (#2972) — show the std ref it names, not its id. */}
            <Box as="span" className="algo-meta mono">{im.role === "primitive" ? (im.ref ?? im.id) : im.id}</Box>
          </Box>
        );
      })}
    </>
  );
}

