// AlgorithmsKitGraph — the GROUP layer draws its links (`the-algorithms-group-layer-draws-its-links`).
//
// A group layer hands the canvas an EMPTY kit: its cards are groups and its edges are group edges. The canvas
// used to draw only `kit.edges`, so the running app showed "64 groups · 246 links" over cards with no line
// between any two of them. These cases render a group layer directly and count what reaches the SVG.
import { describe, it, expect } from "vitest";
import { render } from "@testing-library/react";
import { AlgorithmsKitGraph } from "@/features/algorithms/AlgorithmsKitGraph";
import { layoutGroupGraph, type GroupNode, type GroupEdge } from "@/features/algorithms/lib/knowledge";

const groups: GroupNode[] = [
  { id: "crate:bsc", label: "bsc", kind: "crate", count: 19, origin: "crates" },
  { id: "crate:bsc-util", label: "bsc-util", kind: "crate", count: 77, origin: "crates" },
  { id: "crate:bsc-graph", label: "bsc-graph", kind: "crate", count: 40, origin: "crates" },
];
const groupEdges: GroupEdge[] = [
  { from: "crate:bsc", to: "crate:bsc-util", rel: "depends", weight: 1 },
  { from: "crate:bsc-graph", to: "crate:bsc-util", rel: "composes", weight: 3 },
];

function renderLayer(edges: readonly GroupEdge[]) {
  const layout = layoutGroupGraph(groups, edges);
  return render(
    <AlgorithmsKitGraph kit={{ nodes: [], edges: [] }} layout={layout} selected={null} onSelect={() => {}}
      groups={groups} groupEdges={edges} />,
  );
}

/** The drawn edge LINES — each edge is a `<g>` holding its stroked path plus an arrowhead. */
const lines = (c: HTMLElement) => [...c.querySelectorAll("svg g > path[stroke]")];

describe("the Algorithms group layer", () => {
  it("draws a line for every edge between its groups", () => {
    const { container } = renderLayer(groupEdges);
    expect(container.querySelectorAll("[data-group]")).toHaveLength(3);
    expect(lines(container)).toHaveLength(groupEdges.length);
    for (const p of lines(container)) expect(p.getAttribute("d")).toBeTruthy();
  });

  it("draws a crate dependency solid and a cross-group composes dashed, as the legend keys them", () => {
    const { container } = renderLayer(groupEdges);
    const dashed = lines(container).map((p) => p.getAttribute("stroke-dasharray"));
    expect(dashed.filter((d) => d == null)).toHaveLength(1);
    expect(dashed.filter((d) => d === "4 4")).toHaveLength(1);
  });

  it("draws nothing for an edge whose group is not on the layer", () => {
    const { container } = renderLayer([{ from: "crate:bsc", to: "crate:serde", rel: "depends", weight: 1 }]);
    expect(lines(container)).toHaveLength(0);
  });
});
